ClearAll[corrFromBinned,matchedFlatFlammSeedScan];

corrFromBinned[binned_]:=Correlation[Lookup[binned,"rMean"],Lookup[binned,"EstimatorMean"]];

matchedFlatFlammSeedScan[n_,seeds_List,k_,radius_,nbins_]:=Module[{results},results=Table[Module[{flamm,matchedFlat,resFlamm,resMatched,binnedFlamm,binnedMatched,corrFlamm,corrMatched},Print["Running seed ",seed,"..."];
SeedRandom[seed];
flamm=buildFlammDataset[n,1/2,k];
matchedFlat=buildMatchedFlatFromFlamm3[flamm,k];
resFlamm=evaluateDataset[flamm,radius];
resMatched=evaluateDataset[matchedFlat,radius];
binnedFlamm=radialBinComparisonNoClean[flamm,resFlamm,"LogCMD",nbins];
binnedMatched=radialBinComparisonNoClean[matchedFlat,resMatched,"LogCMD",nbins];
corrFlamm=corrFromBinned[binnedFlamm];
corrMatched=corrFromBinned[binnedMatched];
<|"Seed"->seed,"N"->n,"k"->k,"Radius"->radius,"Bins"->nbins,"MatchedFlatCorrRLogCMD"->N[corrMatched],"FlammCorrRLogCMD"->N[corrFlamm],"Difference"->N[corrFlamm-corrMatched]|>],{seed,seeds}];
results]

